const tmpFd = openSync(snapshotTmpPath, 'w');
try {
  writeSync(tmpFd, Buffer.from(JSON.stringify(snapshot) + '\n', 'utf8'));
  fsyncSync(tmpFd);
} finally {
  closeSync(tmpFd);
}
renameSync(snapshotTmpPath, snapshotPath);
// Make the rename durable too. This is best effort: if syncing the
// directory fails (some platforms/filesystems expose no directory
// fsync), leaving the old log in place is still safe, because every
// byte of it is covered by the new snapshot — recovery will fold it
// harmlessly on reopen.
let dirSynced = false;
try {
  const dirFd = openSync(dir, 'r');
  try {
    fsyncSync(dirFd);
    dirSynced = true;
  } finally {
    closeSync(dirFd);
  }
} catch {
  dirSynced = false;
}

// Truncating while the append handle stays open is not portable
// (on Windows ftruncate of an append handle does not shrink the
// file and later appends can land past a hole). Close it, truncate
// the path, then reopen a fresh append handle.
closeSync(fd);
try {
  truncateSync(logPath, 0);
  writeFileSync(logPath, markerLine(gen));
  if (dirSynced) {
    // A fresh handle only to fsync the truncated directory entry;
    // afterwards reopen the canonical append handle.
    const syncFd = openSync(logPath, 'r+');
    try {
      fsyncSync(syncFd);
    } finally {
      closeSync(syncFd);
    }
  }
  fd = openSync(logPath, 'a');
} catch (err) {
  // Snapshot is durable and covers the entire (still intact) log, so
  // reopening recovers to the marker state; refuse further writes
  // in this instance rather than risk an inconsistent tail.
  broken = true;
  try {
    fd = openSync(logPath, 'a');
  } catch {
    // Nothing usable: leave fd closed; every later op throws.
  }
  throw err;
}
snapshotGen = gen;
baseMessages = messages;

