// Replacing the log must work on Windows: ftruncate() of an open
// append handle does not shrink the file there. Close the handle,
// write the fresh marker-only log to a temp name and atomically
// rename it over the old one (libuv replaces the target), then
// reopen. The whole swap is one synchronous segment, so no reader
// can observe an intermediate state.
closeSync(fd);
let replaced = false;
try {
  writeFileSync(logTmpPath, markerLine(gen));
  renameSync(logTmpPath, logPath);
  replaced = true;
  if (dirSynced) {
    // Best-effort durability for the replacement directory entry.
    const syncFd = openSync(logPath, 'r+');
    try {
      fsyncSync(syncFd);
    } finally {
      closeSync(syncFd);
    }
  }
  fd = openSync(logPath, 'a');
} catch (err) {
  if (!replaced) {
    // New log never landed; the old log is fully covered by the new
    // snapshot regardless. Reopen it so close() still works, but
    // refuse further writes on this instance.
    try {
      fd = openSync(logPath, 'a');
    } catch {
      // Nothing usable: leave fd closed; every later op throws.
    }
  }
  broken = true;
  throw err;
}

