1	import {
2	  openSync,
3	  closeSync,
4	  writeSync,
5	  writevSync,
6	  fsyncSync,
7	  mkdirSync,
8	  readFileSync,
9	  writeFileSync,
10	  truncateSync,
11	  renameSync,
12	  rmSync,
13	  existsSync,
14	} from 'node:fs';
15	import path from 'node:path';
16	import { randomUUID } from 'node:crypto';
17	
18	const LOG_NAME = 'bus.jsonl';
19	const LOG_TMP_NAME = 'bus.log.tmp';
20	const SNAPSHOT_NAME = 'bus.snapshot.json';
21	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
22	
23	/**
24	 * Validate that `value` survives a compact JSON.stringify unchanged.
25	 * JSON silently drops undefined / functions and turns non-finite numbers
26	 * into null; the spec rejects those along with BigInt and circular
27	 * references as TypeError.
28	 */
29	function assertJsonSafe(value, stack = new Set()) {
30	  if (typeof value === 'bigint') {
31	    throw new TypeError('record contains a BigInt');
32	  }
33	  if (typeof value === 'function') {
34	    throw new TypeError('record contains a function');
35	  }
36	  if (typeof value === 'undefined') {
37	    throw new TypeError('record contains undefined');
38	  }
39	  if (typeof value === 'number' && !Number.isFinite(value)) {
40	    throw new TypeError('record contains a non-finite number');
41	  }
42	  if (value !== null && typeof value === 'object') {
43	    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
44	    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
45	      assertJsonSafe(value.valueOf(), stack);
46	      return;
47	    }
48	    if (stack.has(value)) {
49	      throw new TypeError('record contains a circular reference');
50	    }
51	    stack.add(value);
52	    if (Array.isArray(value)) {
53	      for (const item of value) assertJsonSafe(item, stack);
54	    } else {
55	      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
56	    }
57	    stack.delete(value);
58	  }
59	}
60	
61	/**
62	 * Split a jsonl buffer into parsed entries. `durable` is the offset just
63	 * past the final newline; anything beyond it is a torn trailing write.
64	 */
65	function parseLog(raw) {
66	  const entries = [];
67	  let start = 0;
68	  for (let i = 0; i < raw.length; i++) {
69	    if (raw[i] === 0x0a) {
70	      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
71	      start = i + 1;
72	    }
73	  }
74	  return { entries, durable: start };
75	}
76	
77	export function createBus({ path: dir, fsync = false } = {}) {
78	  if (typeof dir !== 'string' || dir.length === 0) {
79	    throw new TypeError('createBus: "path" must be a non-empty string');
80	  }
81	
82	  const logPath = path.join(dir, LOG_NAME);
83	  const logTmpPath = path.join(dir, LOG_TMP_NAME);
84	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
85	  const snapshotTmpPath = path.join(dir, SNAPSHOT_TMP_NAME);
86	
87	  let seq = 0; // seq of the last effective message
88	  let bytes = 0;
89	  let published = 0;
