715	
716	    stats() {
717	      return { seq, bytes, published, replayed };
718	    },
719	
720	    close() {
721	      if (closed) {
722	        return Promise.resolve();
723	      }
724	      closed = true;
725	      // Reject any publish whose dedup reservation is still queued.
726	      for (const [key, p] of pending) {
727	        p.reject(new Error('bus is closed'));
728	        pending.delete(key);
729	      }
730	      // And every reservation held by a batch still waiting in the chain.
731	      for (const [key, g] of groupPending) {
732	        g.reject(new Error('bus is closed'));
733	        groupPending.delete(key);
734	      }
735	      return enqueue(() => {
736	        // A failed compact may have left the append handle unusable; close
737	        // must stay idempotent and never reject.
738	        try {
739	          if (fsync) fsyncSync(fd);
740	        } catch {
741	          // Ignore: the handle may already be closed.
742	        }
743	        try {
744	          closeSync(fd);
745	        } catch {
746	          // Already closed by the compact failure path.
747	        }
748	      });
749	    },
750	  };
751	
752	  return bus;
753	}
