import { rmSync, readFileSync, appendFileSync } from 'node:fs';
import path from 'node:path';
import { tmpdir } from 'node:os';
import { createBus } from '../src/index.js';

const dir = path.join(tmpdir(), `batch-stress-${process.pid}`);
rmSync(dir, { recursive: true, force: true });

// ---- phase 1: heavy concurrency, singles + batches + compacts + replay ----
{
  const bus = createBus({ path: dir, fsync: true });
  const jobs = [];
  let expectedEffective = 0;
  for (let g = 0; g < 50; g++) {
    const recs = [];
    for (let i = 0; i < 10; i++) {
      // sprinkle dedup keys: some within-batch dup, some cross-batch dup
      const dk = (g * 10 + i) % 23 === 0 ? `shared-${(g + i) % 7}` : undefined;
      if (dk === undefined) expectedEffective += 1;
      else if (!recs.some((r) => r.dedupKey === dk)) expectedEffective += 1;
      recs.push({ g, i, ...(dk ? { dedupKey: dk } : {}) });
    }
    jobs.push(bus.publishBatch(recs));
    if (g % 3 === 0) jobs.push(bus.publish({ single: g }));
    if (g % 7 === 0) jobs.push(bus.compact());
    if (g % 5 === 0) jobs.push(bus.replay(0));
  }
  // Account singles (all effective) — but shared keys may also steal seqs
  // from batch records; simplest correctness check is via replay below.
  const results = await Promise.all(jobs);
  const got = await bus.replay(0);
  // seqs must be exactly 1..N with no gaps/dupes
  const seqs = got.map((m) => m.seq);
  const N = seqs.length;
  for (let i = 0; i < N; i++) {
    if (seqs[i] !== i + 1) throw new Error(`seq gap at ${i}: ${seqs[i]}`);
  }
  if (bus.stats().seq !== N) throw new Error('stats.seq mismatch');
  if (bus.stats().published !== N) throw new Error('stats.published mismatch');
  // bytes: recompute from records
  const bytes = got.reduce((n, m) => n + Buffer.byteLength(JSON.stringify(m.record), 'utf8'), 0);
  if (bus.stats().bytes !== bytes) throw new Error(`stats.bytes mismatch ${bus.stats().bytes} vs ${bytes}`);
  // dedup keys resolve after compaction
  for (const k of ['shared-0', 'shared-1']) {
    const ack = await bus.publish({ probe: true, dedupKey: k });
    const stored = got.find((m) => m.record.dedupKey === k);
    if (!stored || ack.seq !== stored.seq || ack.id !== stored.id) throw new Error(`dedup ${k} broken`);
  }
  await bus.close();
  console.log('phase1 OK: effective messages =', N);
}

// ---- phase 2: reopen, verify full history survives ----
{
  const bus = createBus({ path: dir });
  const before = (await bus.replay(0)).map((m) => m.seq);
  await bus.compact();
  await bus.compact();
  const after = await bus.replay(0);
  if (JSON.stringify(after.map((m) => m.seq)) !== JSON.stringify(before)) {
    throw new Error('history changed across compact');
  }
  // record equality too
  const raw0 = readFileSync(path.join(dir, 'bus.jsonl'), 'utf8');
  await bus.close();
  void raw0;
  console.log('phase2 OK: history stable across reopen + double compact, n =', after.length);
}

// ---- phase 3: crash at random offsets of a partial group, repeated ----
{
  for (let trial = 0; trial < 20; trial++) {
    const d = path.join(dir, `crash-${trial}`);
    let bus = createBus({ path: d, fsync: true });
    await bus.publishBatch([{ t: 1 }, { t: 2, dedupKey: 'kk' }]);
    await bus.publish({ t: 3 });
    await bus.close();

    // append a complete-looking partial group then slice it at random length
    const tail =
      JSON.stringify({ t: 'b', id: `g${trial}` }) + '\n' +
      JSON.stringify({ t: 'm', seq: 4, id: 'z', bytes: 1, record: { t: 4 } }) + '\n' +
      JSON.stringify({ t: 'bk', id: `g${trial}` }) + '\n';
    // Sometimes include the full commit (must apply), sometimes cut it.
    const cut = trial % 4 === 0 ? tail.length : 1 + Math.floor(((trial * 37) % (tail.length - 2)));
    appendFileSync(path.join(d, 'bus.jsonl'), tail.slice(0, cut));

    bus = createBus({ path: d });
    const got = await bus.replay(0);
    if (cut === tail.length) {
      if (got.length !== 4 || got[3].seq !== 4) throw new Error(`trial ${trial}: committed group lost`);
    } else {
      if (got.length !== 3) throw new Error(`trial ${trial}: partial group applied, got ${got.length}`);
    }
    // next publish works, seq continuous
    const ack = await bus.publish({ t: 99 });
    if (cut === tail.length) {
      if (ack.seq !== 5) throw new Error('seq after committed partial wrong');
    } else if (ack.seq !== 4) throw new Error('seq after severed partial wrong');
    // log file itself has no dangling bytes (reopen truncated it)
    const raw = readFileSync(path.join(d, 'bus.jsonl'), 'utf8');
    if (!raw.endsWith('\n')) throw new Error('log not normalized');
    await bus.close();
  }
  console.log('phase3 OK: 20 random crash cuts recovered atomically');
}

// ---- phase 4: huge batch writev chunking ----
{
  const d = path.join(dir, 'big');
  const bus = createBus({ path: d });
  const N = 5000;
  const recs = Array.from({ length: N }, (_, i) => ({ i, p: 'x'.repeat(i % 50) }));
  const acks = await bus.publishBatch(recs);
  if (acks.length !== N) throw new Error('ack count');
  const got = await bus.replay(0);
  if (got.length !== N) throw new Error('replay count');
  for (let i = 0; i < N; i++) {
    if (got[i].seq !== i + 1 || got[i].record.i !== i) throw new Error(`big mismatch ${i}`);
  }
  await bus.compact();
  const got2 = await bus.replay(0);
  if (got2.length !== N) throw new Error('post-compact count');
  await bus.close();
  console.log('phase4 OK: batch of', N);
}

rmSync(dir, { recursive: true, force: true });
console.log('ALL STRESS OK');

